<script setup lang="ts">import { computed } from 'vue'; import { formatMoney } from '../../utils/formatters'; import type { ExpenseSummary } from '../../types'; const props = defineProps<{ summary: ExpenseSummary }>(); const cards = computed(() => [{ label: 'Total', value: formatMoney(props.summary.total_amount) }, { label: 'Paid', value: formatMoney(props.summary.paid_amount) }, { label: 'Unpaid', value: formatMoney(props.summary.unpaid_amount) }, { label: 'Pending', value: formatMoney(props.summary.pending_amount) }, { label: 'Transactions', value: String(props.summary.transaction_count) }]);</script>
<template><div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><article v-for="card in cards" :key="card.label" class="card"><p class="text-sm text-slate-500">{{ card.label }}</p><p class="mt-2 text-xl font-semibold tabular-nums">{{ card.value }}</p></article></div></template>
